const payload = $input.first().json.body ?? $input.first().json;

const allowedChannels = [
  'whatsapp', 'email', 'instagram', 'facebook',
  'linkedin', 'webchat', 'other',
];

const missing = ['channel', 'external_message_id', 'text']
  .filter((field) => !payload[field] || String(payload[field]).trim() === '');

if (missing.length > 0) {
  return [{
    json: {
      httpStatus: 400,
      response: {
        ok: false,
        error: 'Datos de entrada incompletos',
        missing,
        expected: {
          channel: 'whatsapp | email | instagram | facebook | linkedin | webchat | other',
          external_message_id: 'ID único del mensaje en el canal',
          text: 'Contenido del mensaje',
        },
      },
    },
  }];
}

if (!allowedChannels.includes(payload.channel)) {
  return [{
    json: {
      httpStatus: 400,
      response: {
        ok: false,
        error: 'Canal no soportado',
        allowed_channels: allowedChannels,
      },
    },
  }];
}

const eventId = payload.event_id || 'evt-' + payload.external_message_id;
const contactId = payload.contact_id || 'contact-' + payload.channel + '-' + payload.external_message_id;
const opportunityId = payload.opportunity_id || 'opp-' + payload.channel + '-' + payload.external_message_id;
const receivedAt = payload.received_at || new Date().toISOString();

return [{
  json: {
    httpStatus: 201,
    response: {
      ok: true,
      event: {
        event_id: eventId,
        type: 'inbound_message_received',
        occurred_at: receivedAt,
        channel: payload.channel,
        external_message_id: payload.external_message_id,
      },
      contact: {
        contact_id: contactId,
        identity: {
          channel: payload.channel,
          value: payload.sender_id || payload.sender || null,
          verified: Boolean(payload.contact_id),
        },
        status: payload.contact_id ? 'confirmed' : 'candidate',
      },
      opportunity: {
        opportunity_id: opportunityId,
        stage: 'new',
        owner: payload.owner || 'unassigned',
        next_step: 'Enviar contacto inicial autorizado',
        next_step_condition: 'inmediatamente tras la validación comercial',
        last_event: eventId,
        summary: 'Prospecto ingresado desde ' + payload.channel + '.',
      },
      outbound_message_draft: {
        opportunity_id: opportunityId,
        channel: payload.channel,
        recipient: payload.sender_id || payload.sender || null,
        text: 'Hola, recibimos tu consulta. Un asesor te responderá a la brevedad.',
        reply_to_external_message_id: payload.external_message_id,
        idempotency_key: 'out-' + eventId,
        status: 'pending_channel_connection',
      },
      next_workflow: 'Conectar persistencia y adaptador de canal antes de enviar el borrador.',
    },
  },
}];
